    // for (i = 0; i < n; i++)
    //   for (j = 0; j < n; j++)
    //     C[i][j] = ((i*j+2)%m) / m;
    //
    // C array C[i][j] is mapped to Buffer C(j, i) with shape (n, n).
    init_C(j, i) = cast<num_t>((i * j + 2) % m) / Expr(m);

    // Simple CPU schedule: row-parallel, vectorized along the
    // innermost (contiguous) x-dimension.
    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());

    init_A.compute_root()
          .reorder(j, i)        // j (x) innermost, contiguous in memory
          .vectorize(j, vec)
          .parallel(i);

    init_C.compute_root()
          .reorder(j, i)
          .vectorize(j, vec)
          .parallel(i);

    init_A.realize(A);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;
    int m = M;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    // C is N x N in C as C[i][j], map to Buffer C(j, i) => shape (n, n)
    // A is N x M in C as A[i][j], map to Buffer A(j, i) => shape (m, n)
    Halide::Buffer<num_t, 2> C(n, n);
    Halide::Buffer<num_t, 2> A(m, n);

    // ImageParams corresponding to C and A
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Initialize data using Halide
    init_array(n, m, &alpha, &beta, C, A);

    // Bind ImageParams to the initialized buffers
    C_param.set(C);
    A_param.set(A);

    // Halide Vars and RDom
    Var i("i"), j("j");
    // k iterates over the first dimension of A (M)
    RDom k(0, A.dim(0).extent(), "k");

    // Build the SYRK kernel in Halide
    // BLAS SYRK:
    // C := alpha * A * A^T + beta * C
    //
    // Original C kernel:
    //
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_M; k++) {
    //     for (j = 0; j <= i; j++)
    //       C[i][j] += alpha * A[i][k] * A[j][k];
    //   }
    // }
    //
    // We express this as:
    //   C_new[i][j] = C[i][j]                                  if j > i
    //               = beta * C[i][j] +
    //                 alpha * sum_k A[i][k] * A[j][k]          if j <= i
    //
    // Mapping to Buffer / ImageParam indices:
    //   C[i][j]   -> C_param(j, i)
    //   A[i][k]   -> A_param(k, i)
    //   A[j][k]   -> A_param(k, j)
    //
    // We'll compute a full N x N Func, and use select(j <= i, ..., orig)
    // to restrict updates logically to the lower triangle; the upper
    // triangle is passed through unchanged.

    Func syrk("syrk");

    Expr alpha_expr = Expr(alpha);
    Expr beta_expr  = Expr(beta);

    Expr orig = C_param(j, i);

    // Pure definition: scale lower triangle by beta, keep upper triangle unchanged.
    syrk(j, i) = select(j <= i,
                        beta_expr * orig,
                        orig);

    // Reduction definition over k: add alpha * A[i][k] * A[j][k] for the lower triangle.
    syrk(j, i) += select(j <= i,
                         alpha_expr * A_param(k, i) * A_param(k, j),
                         cast<num_t>(0));

    // --------------------------
    // Scheduling for performance
    // --------------------------

    Target target = get_host_target();
    const int vec = target.natural_vector_size(type_of<num_t>());

    // Compute the whole result at once.
    syrk.compute_root();

    // Memory layout:
    //   C and syrk are stored as Buffer(x = j, y = i) in row-major order.
    //   Thus, j is the fastest-varying dimension in memory.
    //
    // We therefore:
    //   - reorder to make j the innermost loop for good locality,
    //   - vectorize across j,
    //   - parallelize across i (rows), which are independent for this kernel.
    syrk
        .reorder(j, i)         // j (x) innermost, contiguous in memory
        .vectorize(j, vec)     // SIMD across columns
        .parallel(i);          // parallelize across rows

    // For the reduction update:
    //   default order is (i, j, k); we reorder to (i, k, j):
    //   - i outermost (so we can parallelize by i),
    //   - k in the middle (reusing A_param(k, i) across j),
    //   - j innermost and vectorized (contiguous accesses to A_param(k, j)
    //     and syrk(j, i)).
    syrk.update()
        .reorder(j, k, i)      // innermost->outermost: j, k, i => loops: i, k, j
        .vectorize(j, vec)
        .parallel(i);

    // Compile the kernel to machine code with this target
    syrk.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result into C (logically in-place w.r.t. original code)
    syrk.realize(C);

    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (similar spirit to the original print_array), guarded
    // the same way as in the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C array C[ii][jj] -> Buffer C(jj, ii)
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
