/**
 * Array initialization, translated from the original C version.
 *
 * We keep the same formulas but add a schedule that parallelizes across rows
 * and vectorizes across the contiguous x-dimension to improve initialization
 * throughput.
 */
static
void init_array(int n, int m,
                num_t *alpha,
                num_t *beta,
                Halide::Buffer<num_t, 2> C,
                Halide::Buffer<num_t, 2> A) {
