    // for (i = 0; i < n; i++)
    //   for (j = 0; j < m; j++)
    //     A[i][j] = ((i*j+1)%n) / n;
    //
    // C array A[i][j] is mapped to Buffer A(j, i) with shape (m, n).
    init_A(j, i) = cast<num_t>(((i * j + 1) % n)) / cast<int>(n);

    // Original C:
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < n; j++)
    //     C[i][j] = ((i*j+2)%m) / m;
    //
    // C array C[i][j] is mapped to Buffer C(j, i) with shape (n, n).
    init_C(j, i) = cast<num_t>(((i * j + 2) % m)) / cast<int>(m);

    // Simple but effective schedule: parallelize across rows (i),
    // vectorize across contiguous columns (j).
    const int vec_width = Halide::natural_vector_size<num_t>();

    init_A
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    init_C
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    init_A.realize(A);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;
    int m = M;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    // C is N x N in C as C[i][j], map to Buffer C(j, i) => shape (n, n)
    // A is N x M in C as A[i][j], map to Buffer A(j, i) => shape (m, n)
    Halide::Buffer<num_t, 2> C(n, n);
    Halide::Buffer<num_t, 2> A(m, n);

    // ImageParams corresponding to C and A
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Initialize data using Halide
    init_array(n, m, &alpha, &beta, C, A);

    // Bind ImageParams to the initialized Buffers
    C_param.set(C);
    A_param.set(A);

    // Halide Vars and RDom
    Var i("i"), j("j");
    // k iterates over columns of A (first dimension of A_param)
    RDom k(0, A.dim(0).extent(), "k");

    // Build the SYRK kernel in Halide
    // BLAS SYRK:
    // C := alpha * A * A^T + beta * C
    //
    // Original C kernel:
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_M; k++) {
    //     for (j = 0; j <= i; j++)
    //       C[i][j] += alpha * A[i][k] * A[j][k];
    //   }
    // }
    //
    // We express this as:
    // C_new[i][j] = C[i][j]                                      if j > i
    //             = beta * C[i][j] + alpha * sum_k A[i][k] * A[j][k]  if j <= i
    //
    // Mapping to Halide buffers:
    //   C[i][j]   -> C_param(j, i)
    //   A[i][k]   -> A_param(k, i)
    //   A[j][k]   -> A_param(k, j)
    //
    // We compute a full N x N Func, and for j > i we simply forward
    // the original C value unchanged, exactly matching the original
    // semantics for the upper triangle.

    Func syrk("syrk");

    Expr alpha_expr = cast<num_t>(Expr(alpha));
    Expr beta_expr  = cast<num_t>(Expr(beta));

    Expr orig = C_param(j, i);

    // Pure definition: scale lower triangle by beta, keep upper triangle unchanged.
    syrk(j, i) = select(j <= i,
                        beta_expr * orig,
                        orig);

    // Reduction over k: add alpha * A[i][k] * A[j][k] for lower triangle.
    syrk(j, i) += select(j <= i,
                         alpha_expr *
                             A_param(k, i) * A_param(k, j),
                         cast<num_t>(0));

    // --------------------------------------------------------------------
    // Schedule
    //
    // Storage layout:
    //   C_param / syrk are indexed as (j, i). Dimension 0 (j) is contiguous in
    //   memory, so we want j to be the innermost loop and vectorized to get
    //   dense vector loads/stores for C.
    //
    // Parallelization:
    //   Different rows i of C are independent, so we parallelize across blocks
    //   of rows (i_outer). This gives good coarse-grain parallelism across cores.
    //
    // Vectorization:
    //   We vectorize across the contiguous j dimension using the natural vector
    //   width for num_t on the host.
    //
    // Reduction:
    //   For the update definition we keep the reduction variable k inside the
    //   tiling loops, but still outside the innermost vectorized j-inner loop,
    //   so each vector lane accumulates over k independently. We parallelize
    //   over i_outer, which is a pure variable, so there are no write races.
    // --------------------------------------------------------------------
    const int vec = Halide::natural_vector_size<num_t>();
    const int tile_i = 32;  // tile size in i (rows); moderate for cache and parallelism

    Var io("io"), ii("ii"), jo("jo"), ji("ji");

    // Schedule the pure definition.
    syrk
        .compute_root()
        // Tile i into (io, ii) and j into (jo, ji).
        .split(i, io, ii, tile_i)
        .split(j, jo, ji, vec)
        // Make ji (inner j) innermost for vectorization, then jo, then ii, then io.
        .reorder(ji, jo, ii, io)
        .vectorize(ji)
        .parallel(io);

    // Schedule the update (reduction) definition in a way consistent
    // with the pure stage: same tiling and parallelization. Now we
    // also include k in the loop nest and keep it just outside the
    // vectorized ji loop.
    syrk.update()
        .split(i, io, ii, tile_i)
        .split(j, jo, ji, vec)
        // Order from innermost to outermost: ji (vectorized j), k, jo, ii, io.
        .reorder(ji, k, jo, ii, io)
        .vectorize(ji)
        .parallel(io);

    // Compile the kernel to machine code for the host.
    syrk.compile_jit();

    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result into C (in-place semantics w.r.t the original code).
    syrk.realize(C);

    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (similar spirit to the original print_array), guarded
    // the same way as in the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
