    Target init_target = get_host_target();
    const int vec_width = init_target.natural_vector_size(type_of<num_t>());

    init_A.vectorize(j, vec_width).parallel(i);
    init_C.vectorize(j, vec_width).parallel(i);

    init_A.realize(A);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;
    int m = M;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    // C is N x N in C as C[i][j], map to Buffer C(j, i) => shape (n, n)
    // A is N x M in C as A[i][j], map to Buffer A(j, i) => shape (m, n)
    Halide::Buffer<num_t, 2> C(n, n);
    Halide::Buffer<num_t, 2> A(m, n);

    // ImageParams corresponding to C and A
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Initialize data using Halide
    init_array(n, m, &alpha, &beta, C, A);

    // Halide Vars and RDom
    Var i("i"), j("j");
    // A is (k, i) = (M, N), so k iterates over the first dimension of A.
    RDom k(0, A.dim(0).extent(), "k"); // k over M (first dimension of A)

    // Build the SYRK kernel in Halide
    // BLAS SYRK:
    // C := alpha * A * A^T + beta * C
    //
    // Original C kernel:
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_M; k++) {
    //     for (j = 0; j <= i; j++)
    //       C[i][j] += alpha * A[i][k] * A[j][k];
    //   }
    // }
    //
    // We express this as:
    //   C_new[i][j] = C[i][j]                                         if j > i
    //               = beta * C[i][j] + alpha * sum_k A[i][k] A[j][k]  if j <= i
    //
    // Remember mapping:
    //   C[i][j]   -> C_param(j, i)
    //   A[i][k]   -> A_param(k, i)
    //   A[j][k]   -> A_param(k, j)
    //
    // We'll compute a full N x N Func, and use select(j <= i, ..., orig)
    // so that the upper triangle (j > i) is left unchanged.

    Func syrk("syrk");

    // Promote scalar alpha/beta to Halide Exprs of the correct type.
    Expr alpha_expr = Expr(alpha); // type matches num_t
    Expr beta_expr  = Expr(beta);

    Expr orig = C_param(j, i);

    // Pure definition: scale lower triangle by beta, keep upper triangle unchanged.
    syrk(j, i) = select(j <= i,
                        cast<num_t>(beta_expr) * orig,
                        orig);

    // Reduction over k: add alpha * A[i][k] * A[j][k] for the lower triangle only.
    // For j > i, we add zero, so values stay equal to 'orig', matching the C kernel.
    syrk(j, i) += select(j <= i,
                         cast<num_t>(alpha_expr) *
                             A_param(k, i) * A_param(k, j),
                         cast<num_t>(0));

    // -----------------
    // Schedule for syrk
    // -----------------
    //
    // Memory layout:
    //   - C and A are row-major in their first dimension (x = j or k).
    //   - So we want 'j' innermost for vectorization.
    //
    // We tile the (j, i) space to improve cache locality and parallelize over tiles
    // in the i (row) dimension. The reduction over k remains innermost inside each
    // (j, i) tile, which gives good reuse of A_param(k, i) across j.
    Var jo("jo"), io("io"), ji("ji"), ii("ii");

    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // Tile dimensions; chosen to be reasonably cache-friendly.
    const int J_TILE = 64;
    const int I_TILE = 32;

    // Tile over (j, i), parallelize outer tiles, and vectorize along j.
    syrk
        .tile(j, i, jo, io, ji, ii, J_TILE, I_TILE)
        .parallel(io)              // parallelize over tiles in the i-direction
        .vectorize(ji, vec_width); // vectorize across contiguous j

    // For the update step (the reduction over k), reorder loops so that:
    //   inner:  ji (vectorized j)
    //   then:   ii (within-tile i)
    //   then:   k  (reduction)
    //   outer:  jo, io (tile indices)
    //
    // This keeps the vectorized j dimension innermost while still allowing
    // us to sweep k with good reuse of A_param(k, i) across ji.
    syrk.update()
        .reorder(ji, ii, k, jo, io)
        .vectorize(ji, vec_width);

    // Bind ImageParams
    C_param.set(C);
    A_param.set(A);

    // Compile the kernel to machine code for the host target
    syrk.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result into C (in-place semantics w.r.t the original code)
    syrk.realize(C);

    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (similar spirit to the original print_array), guarded
    // the same way as in the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C array C[ii][jj] -> Buffer C(jj, ii)
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
